.admin-order-actions{white-space:nowrap}.admin-inline-form{display:inline-block;margin:0 4px 0 0}.admin-decision-button{border:0;border-radius:8px;padding:11px 15px;color:#fff;font-size:13px;font-weight:800;cursor:pointer}.admin-decision-button.is-approve{background:#18a56b}.admin-decision-button.is-reject{background:#e91b2d}.admin-action-unavailable{color:#9aa1ac}.admin-confirm-modal{position:fixed;inset:0;z-index:100;display:grid;place-items:center}.admin-confirm-modal[hidden]{display:none}.admin-confirm-backdrop{position:absolute;inset:0;background:rgba(12,14,18,.68);backdrop-filter:blur(3px)}.admin-confirm-dialog{position:relative;width:min(560px,calc(100% - 32px));padding:42px 44px 38px;border:1px solid rgba(233,27,45,.14);border-radius:22px;background:#fff;box-shadow:0 30px 90px rgba(0,0,0,.3);text-align:center}.admin-confirm-icon{display:grid;place-items:center;width:68px;height:68px;margin:0 auto 20px;border-radius:50%;background:#fff1d9;color:#d98a00;font-size:34px;font-weight:900;box-shadow:0 8px 20px rgba(217,138,0,.15)}.admin-confirm-dialog h2{margin:0 0 12px;color:#15171b;font-size:30px;letter-spacing:-.02em}.admin-confirm-dialog p{margin:0 auto;color:#697382;font-size:16px;line-height:1.6;max-width:430px}.admin-reject-note{display:block;margin-top:22px;text-align:left;color:#353d49;font-size:14px;font-weight:800}.admin-reject-note textarea{display:block;width:100%;margin-top:9px;padding:13px;border:1px solid #dfe3e8;border-radius:10px;resize:vertical;font:inherit;font-size:14px;line-height:1.5}.admin-confirm-actions{display:flex;justify-content:center;gap:12px;margin-top:30px}.admin-modal-button{min-width:130px;border:0;border-radius:9px;padding:14px 22px;font-size:14px;font-weight:800;cursor:pointer}.admin-modal-button.is-cancel{background:#eef0f3;color:#4c5562}.admin-modal-button.is-confirm{background:#e91b2d;color:#fff;box-shadow:0 8px 18px rgba(233,27,45,.2)}.admin-modal-button.is-confirm.is-approve{background:#18a56b;box-shadow:0 8px 18px rgba(24,