@push('scripts')
<script>
(() => { const modal=document.querySelector('[data-decision-modal]'); if(!modal)return; let targetForm=null; const title=modal.querySelector('[data-decision-title]'),message=modal.querySelector('[data-decision-message]'),note=modal.querySelector('[data-reject-note]'),input=modal.querySelector('[data-reject-input]'),submit=modal.querySelector('[data-decision-submit]'); const close=()=>{modal.hidden=true;targetForm=null;note.hidden=true;input.value='';document.body.style.overflow='';}; document.querySelectorAll('[data-decision]').forEach(button=>button.addEventListener('click',()=>{targetForm=document.getElementById(button.dataset.form);const rejecting=button.dataset.decision==='reject';title.textContent=rejecting?'Konfirmasi Penolakan Pesanan':'Konfirmasi Persetujuan Pesanan';message.textContent=rejecting?'Apakah Anda yakin ingin menolak pesanan ini? Pesanan tidak akan diproses ke tahap berikutnya.':'Apakah Anda yakin ingin menyetujui pesanan ini? Pesanan akan diproses ke tahap pembayaran.';note.hidden=!rejecting;submit.textContent=rejecting?'Ya, Tolak Pesanan':'Ya, Setujui Pesanan';submit.classList.toggle('is-approve',!rejecting);modal.hidden=false;document.body.style.overflow='hidden';submit.focus();})); modal.querySelectorAll('[data-decision-cancel]').forEach(button=>button.addEventListener('click',close)); submit.addEventListener('click',()=>{if(!targetForm)return;if(!note.hidden){targetForm.querySelector('[name="catatan_admin"]').value=input.value.trim()||'Pesanan ditolak oleh admin.';}targetForm.submit();}); document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!modal.hidden)close();}); })();
</script>
